class ModelNew(nn.Module):
    """
    Computes Triplet Margin Loss using custom PTX kernels with grid-level
    parallelism across multiple CTAs for better GPU utilization.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)
        self.NUM_BLOCKS = 128
        self.BLOCK_SIZE = 256
    def forward(self, anchor, positive, negative):
        assert anchor.shape == positive.shape == negative.shape
        assert anchor.dim() == 2
        anchor = anchor.contiguous()
        positive = positive.contiguous()
        negative = negative.contiguous()
        batch_size, dim = anchor.shape
        num_blocks = self.NUM_BLOCKS
        block_size = self.BLOCK_SIZE
        partial_sums = torch.empty((num_blocks,), dtype=torch.float32, device=anchor.device)
        output = torch.empty((), dtype=torch.float32, device=anchor.device)
        module = _get_ptx_module()
        module.launch(
            "triplet_margin_loss_partial",
            grid=(num_blocks, 1, 1),
            block=(block_size, 1, 1),
            arguments=[
                anchor,
                positive,
                negative,
                partial_sums,
                f32(self.margin),
                u32(batch_size),
                u32(dim),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(anchor.device),
        )
        module.launch(
            "reduce_partial",
            grid=(1, 1, 1),
            block=(num_blocks, 1, 1),
            arguments=[
                partial_sums,
                output,
                u32(batch_size),
                u32(num_blocks),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(anchor.device),
        )
        return output

